from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import xml.etree.ElementTree as ET,json,struct
root=Path(__file__).resolve().parent
cfg={}
for line in Path('/private/tmp/prusa-project-config.txt').read_text().splitlines():
 if line.startswith('; ') and ' = ' in line:
  k,v=line[2:].split(' = ',1);cfg[k]=v
cfg.update(printer_technology='FFF',bed_shape='0x0,300x0,300x300,0x300',max_print_height='300',printer_model='',printer_variant='0.4',printer_settings_id='K1 MAX LAYOUT ONLY - SELECT YOUR CALIBRATED MACHINE PROFILE',print_settings_id='Turret V8 - 0.24 mm removable supports',filament_settings_id='Creality Hyper PLA - assumed from user',layer_height='0.24',first_layer_height='0.24',nozzle_diameter='0.4',filament_diameter='1.75',perimeters='4',top_solid_layers='5',bottom_solid_layers='5',fill_density='20%',fill_pattern='gyroid',support_material='1',support_material_auto='1',support_material_style='snug',support_material_threshold='45',support_material_contact_distance='0.24',support_material_bottom_contact_distance='0.24',support_material_xy_spacing='0.4',support_material_interface_layers='2',support_material_buildplate_only='0',brim_width='5',gcode_flavor='klipper',start_gcode='',end_gcode='',before_layer_gcode='',layer_gcode='',after_layer_gcode='',toolchange_gcode='',print_host='',printhost_apikey='',printhost_cafile='',filament_type='PLA',temperature='220',first_layer_temperature='220',bed_temperature='45',first_layer_bed_temperature='45',perimeter_speed='80',external_perimeter_speed='50',infill_speed='100',solid_infill_speed='80',top_solid_infill_speed='45',support_material_speed='70',support_material_interface_speed='40',bridge_speed='25',first_layer_speed='30',travel_speed='180',default_acceleration='2000')
text='; Layout and removable support settings only. Select the real K1 Max machine and filament profiles before slicing.\n'+'\n'.join('; '+k+' = '+v for k,v in sorted(cfg.items()))+'\n'
(root/'PROCESS_SETTINGS.ini').write_text('\n'.join(k+' = '+v for k,v in sorted(cfg.items()))+'\n')
ns='http://schemas.microsoft.com/3dmanufacturing/core/2015/02';ET.register_namespace('',ns)
rows=json.loads((root/'layout_report.json').read_text())
for row in rows:
 model=ET.Element('{'+ns+'}model',unit='millimeter');meta=ET.SubElement(model,'{'+ns+'}metadata',name='Title');meta.text='V8 K1 Max - select real machine and filament profiles before slicing'
 resources=ET.SubElement(model,'{'+ns+'}resources');build=ET.SubElement(model,'{'+ns+'}build');objconfig=ET.Element('config')
 # Recover named component transforms directly from source triangles.
 for oi,p in enumerate(row['parts'],1):
  import re,math
  verts=[tuple(map(float,m)) for m in re.findall(r'vertex\s+([-\d.e+]+)\s+([-\d.e+]+)\s+([-\d.e+]+)',(root.parent/'stl'/(p['name']+'.stl')).read_text())]
  lo=[min(v[i] for v in verts) for i in range(3)];verts=[tuple(v[i]-lo[i] for i in range(3)) for v in verts]
  vs=[]
  for x,y,z in verts:
   if p['turn']:x,y=p['dx']-y,x
   vs.append((x+p['x']+8,y+p['y']+8,z))
  name=p['name']+'_'+str(p['copy']);obj=ET.SubElement(resources,'{'+ns+'}object',id=str(oi),type='model',name=name);mesh=ET.SubElement(obj,'{'+ns+'}mesh');vv=ET.SubElement(mesh,'{'+ns+'}vertices');tt=ET.SubElement(mesh,'{'+ns+'}triangles');lookup={}
  ids=[]
  for v in vs:
   if v not in lookup:
    lookup[v]=len(lookup);ET.SubElement(vv,'{'+ns+'}vertex',x=str(v[0]),y=str(v[1]),z=str(v[2]))
   ids.append(lookup[v])
  for i in range(0,len(ids),3):ET.SubElement(tt,'{'+ns+'}triangle',v1=str(ids[i]),v2=str(ids[i+1]),v3=str(ids[i+2]))
  ET.SubElement(build,'{'+ns+'}item',objectid=str(oi))
  co=ET.SubElement(objconfig,'object',id=str(oi),instances_count='1');ET.SubElement(co,'metadata',type='object',key='name',value=name)
  vol=ET.SubElement(co,'volume',firstid='0',lastid=str(len(ids)//3-1));ET.SubElement(vol,'metadata',type='volume',key='name',value=name)
 filename=row['file'].replace('.stl','.3mf')
 with ZipFile(root/filename,'w',ZIP_DEFLATED) as z:
  z.writestr('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/></Types>')
  z.writestr('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>')
  z.writestr('3D/3dmodel.model',ET.tostring(model,encoding='utf-8',xml_declaration=True));z.writestr('Metadata/Slic3r_PE.config',text);z.writestr('Metadata/Slic3r_PE_model.config',ET.tostring(objconfig,encoding='utf-8',xml_declaration=True))
 (root/filename.replace('.3mf','.scad')).write_text('// Batch preview only; supports are generated by the filament slicer.\nimport("'+row['file']+'");\n')
 print(filename,len(row['parts']),'named objects')
